import{_ as t,o as e,c as o,a2 as c}from"./chunks/framework.CWWEQfK7.js";const l=JSON.parse('{"title":"环境变量参考","description":"按共享配置和五个模块查询环境变量的类型、代码默认值、条件、范围、用途与源码位置。","frontmatter":{"page_id":"configuration-environment-reference","description":"按共享配置和五个模块查询环境变量的类型、代码默认值、条件、范围、用途与源码位置。"},"headers":[],"relativePath":"configuration/environment-reference.md","filePath":"configuration/environment-reference.md","lastUpdated":1786627803000}'),r={name:"configuration/environment-reference.md"};function a(_,d,h,E,P,S){return e(),o("div",null,[...d[0]||(d[0]=[c('<h1 id="环境变量参考" tabindex="-1">环境变量参考 <a class="header-anchor" href="#环境变量参考" aria-label="Permalink to &quot;环境变量参考&quot;">​</a></h1><p>本页记录当前源码实际读取的公开配置。表中的“默认值”是代码默认值，不是生产建议；<code>change-me</code>、空字符串和 <code>.env.example</code> 中的 <code>replace-me</code> 都不能作为真实密钥。</p><p>后端使用 <code>.env</code>，进程环境中的同名值优先于 <code>.env</code>。前端使用 Vite 环境文件。未识别的后端字段会被忽略，因此组合仓库可以提供一份配置全集，但拼写错误也可能不会在启动时直接报错。</p><p>变量名后的 <code>†</code> 表示该字段还可以由数据库中的 <code>runtime.&lt;小写字段名&gt;</code> 覆盖。API 在启动后每约 <code>30</code> 秒刷新自己的运行时设置；Worker 在轮询和领取任务时刷新；MCP 在认证请求中刷新 Core 共享运行时设置。数据库覆盖不存在时，才使用进程环境或 <code>.env</code> 的值。</p><h2 id="源码缩写" tabindex="-1">源码缩写 <a class="header-anchor" href="#源码缩写" aria-label="Permalink to &quot;源码缩写&quot;">​</a></h2><table tabindex="0"><thead><tr><th>缩写</th><th>当前源码位置</th></tr></thead><tbody><tr><td>C</td><td><code>core/src/ershu/core/config.py</code></td></tr><tr><td>CR</td><td><code>core/src/ershu/services/runtime_settings.py</code></td></tr><tr><td>WR</td><td><code>core/src/ershu/services/worker_runtime_contract.py</code></td></tr><tr><td>A</td><td><code>api/src/ershu/api/runtime_settings.py</code></td></tr><tr><td>W</td><td><code>worker/src/ershu/workers/runtime_settings.py</code></td></tr><tr><td>M</td><td><code>mcp/src/ershu/mcp/runtime_settings.py</code></td></tr><tr><td>F</td><td><code>frontend/lib/api/core.ts</code>、<code>frontend/vite.config.ts</code></td></tr></tbody></table><p>“无显式范围”表示当前类型可以解析，但源码没有再声明数值上下限或枚举。它不等于任何值都适合生产。</p><h2 id="后端共享-进程和存储" tabindex="-1">后端共享：进程和存储 <a class="header-anchor" href="#后端共享-进程和存储" aria-label="Permalink to &quot;后端共享：进程和存储&quot;">​</a></h2><table tabindex="0"><thead><tr><th>配置项</th><th>模块</th><th>类型</th><th>代码默认值</th><th>必填或条件</th><th>范围</th><th>用途</th><th>来源</th></tr></thead><tbody><tr><td><code>APP_NAME</code></td><td>Core、API、Worker、MCP</td><td>字符串</td><td><code>Ershu</code></td><td>否</td><td>无显式范围</td><td>服务显示名称</td><td>C</td></tr><tr><td><code>APP_VERSION</code></td><td>Core、API、Worker、MCP</td><td>字符串</td><td><code>1.0.0.post20260812</code></td><td>否</td><td>无显式范围</td><td>API 与服务版本信息</td><td>C</td></tr><tr><td><code>ENVIRONMENT</code></td><td>Core、API、Worker、MCP</td><td>字符串</td><td><code>development</code></td><td>否</td><td><code>prod</code>、<code>production</code> 会启用生产校验</td><td>控制开发模式和生产安全检查</td><td>C、A、M</td></tr><tr><td><code>LOG_LEVEL</code></td><td>API、Worker、MCP</td><td>字符串</td><td><code>INFO</code></td><td>否</td><td>无显式枚举</td><td>日志级别</td><td>C</td></tr><tr><td><code>DATABASE_URL</code></td><td>API、Worker、MCP、Core 工具</td><td>字符串</td><td><code>postgresql+asyncpg://ershu:ershu_password@localhost:5432/ershu</code></td><td>实际部署必须指向可用库</td><td>无显式范围</td><td>PostgreSQL 异步连接地址</td><td>C</td></tr><tr><td><code>DATABASE_POOL_SIZE</code></td><td>API、Worker、MCP、Core 工具</td><td>整数</td><td><code>5</code></td><td>否</td><td>无显式范围</td><td>常驻数据库连接数</td><td>C</td></tr><tr><td><code>DATABASE_MAX_OVERFLOW</code></td><td>API、Worker、MCP、Core 工具</td><td>整数</td><td><code>10</code></td><td>否</td><td>无显式范围</td><td>连接池可临时增加的连接数</td><td>C</td></tr><tr><td><code>DATABASE_POOL_TIMEOUT_SECONDS</code></td><td>API、Worker、MCP、Core 工具</td><td>整数</td><td><code>30</code></td><td>否</td><td>无显式范围</td><td>等待数据库连接的秒数</td><td>C</td></tr><tr><td><code>MILVUS_URI</code></td><td>API、Worker、MCP</td><td>字符串</td><td><code>http://localhost:19530</code></td><td>使用向量索引时必须可达</td><td>无显式范围</td><td>Milvus 服务地址</td><td>C</td></tr><tr><td><code>MILVUS_TOKEN</code></td><td>API、Worker、MCP</td><td>字符串</td><td>空</td><td>Milvus 开启认证时必填</td><td>无显式范围</td><td>Milvus 凭据</td><td>C</td></tr><tr><td><code>MILVUS_DB_NAME</code></td><td>API、Worker、MCP</td><td>字符串</td><td><code>default</code></td><td>否</td><td>无显式范围</td><td>Milvus 数据库名称</td><td>C</td></tr></tbody></table><p>API、Worker 与 MCP 应连接同一 PostgreSQL 和同一 Milvus 数据库。否则任务、权限、提交和索引状态会互相对不上。</p><h2 id="后端共享-代理、会话和密钥" tabindex="-1">后端共享：代理、会话和密钥 <a class="header-anchor" href="#后端共享-代理、会话和密钥" aria-label="Permalink to &quot;后端共享：代理、会话和密钥&quot;">​</a></h2><table tabindex="0"><thead><tr><th>配置项</th><th>模块</th><th>类型</th><th>代码默认值</th><th>必填或条件</th><th>范围</th><th>用途</th><th>来源</th></tr></thead><tbody><tr><td><code>PROXY_HEADERS</code></td><td>API、MCP</td><td>布尔值</td><td><code>true</code></td><td>反向代理后通常保持开启</td><td><code>true</code> 或 <code>false</code></td><td>是否信任允许来源传来的代理头</td><td>C</td></tr><tr><td><code>FORWARDED_ALLOW_IPS</code></td><td>API、MCP</td><td>字符串</td><td><code>127.0.0.1</code></td><td>代理不在本机时要修改</td><td>Uvicorn 接受的 IP 或 CIDR 文本</td><td>限定哪些代理可以提供转发信息</td><td>C</td></tr><tr><td><code>SECRET_KEY</code></td><td>API、MCP</td><td>字符串</td><td><code>change-me</code>，无效</td><td>启动必填</td><td>至少 32 个字符；不能是已知弱值；与另两项不同</td><td>签名会话等服务端数据</td><td>C、A、M</td></tr><tr><td><code>ENCRYPTION_KEY</code></td><td>API、Worker、MCP</td><td>字符串</td><td>空，无效</td><td>启动必填</td><td>至少 32 个字符；不能是已知弱值；API/MCP 中与另两项不同</td><td>加密模型、仓库和 Webhook 等敏感值</td><td>C、A、W、M</td></tr><tr><td><code>MCP_KEY_PEPPER</code></td><td>API、MCP</td><td>字符串</td><td>空，无效</td><td>启动必填</td><td>至少 32 个字符；不能是已知弱值；与另两项不同</td><td>MCP 密钥哈希的服务端独立秘密</td><td>C、A、M</td></tr><tr><td><code>SESSION_IDLE_TIMEOUT_MINUTES</code></td><td>API、MCP</td><td>整数</td><td><code>120</code></td><td>否</td><td>无显式范围</td><td>判断用户会话空闲超时</td><td>C</td></tr></tbody></table><p>三项密钥在 API 与 MCP 之间必须一致，三项彼此必须不同。Worker 至少要使用相同的 <code>ENCRYPTION_KEY</code>，否则无法读取 API 写入的加密数据。</p><h2 id="后端共享-任务、搜索和仓库访问" tabindex="-1">后端共享：任务、搜索和仓库访问 <a class="header-anchor" href="#后端共享-任务、搜索和仓库访问" aria-label="Permalink to &quot;后端共享：任务、搜索和仓库访问&quot;">​</a></h2><table tabindex="0"><thead><tr><th>配置项</th><th>模块</th><th>类型</th><th>代码默认值</th><th>必填或条件</th><th>范围</th><th>用途</th><th>来源</th></tr></thead><tbody><tr><td><code>RUN_QUEUE_LEASE_TIMEOUT_SECONDS</code>†</td><td>API、Worker</td><td>整数</td><td><code>600</code></td><td>否</td><td><code>300</code>–<code>86400</code></td><td>判断运行任务租约何时失效并可恢复</td><td>C、CR</td></tr><tr><td><code>ANALYSIS_RUN_RETENTION_COUNT</code>†</td><td>API、Worker</td><td>整数</td><td><code>50</code></td><td>否</td><td><code>1</code>–<code>10000</code></td><td>每个项目保留的完成、失败或取消运行数；活动运行不删除</td><td>C、CR</td></tr><tr><td><code>SEARCH_INDEX_BATCH_SIZE</code>†</td><td>API、Worker</td><td>整数</td><td><code>2000</code></td><td>否</td><td><code>100</code>–<code>20000</code></td><td>每批重建和写入的搜索块上限</td><td>C、CR</td></tr><tr><td><code>REPOSITORY_STORAGE_PATH</code>†</td><td>API、Worker、MCP</td><td>字符串</td><td><code>.ershu/repo_cache</code></td><td>否</td><td>非空，去空格后最多 255 个字符</td><td>远程仓库缓存和受控工作区根目录</td><td>C、CR</td></tr><tr><td><code>TRUSTED_LOCAL_PATHS</code>†</td><td>API、Worker、MCP</td><td>字符串列表，也接受逗号或换行文本</td><td><code>[]</code></td><td>使用本地仓库时必填</td><td>最多 50 项</td><td>允许登记的本地仓库根目录</td><td>C、CR</td></tr><tr><td><code>ALLOW_DEV_OPEN_LOCAL_REPOSITORY_PATHS</code>†</td><td>API、Worker、MCP</td><td>布尔值</td><td><code>false</code></td><td>仅开发环境可选</td><td>生产环境必须为 <code>false</code></td><td>开发时允许未被白名单覆盖或没有 <code>.git</code> 的本地路径</td><td>C、CR</td></tr><tr><td><code>GIT_COMMAND_TIMEOUT_SECONDS</code>†</td><td>API、Worker、MCP</td><td>整数</td><td><code>120</code></td><td>否</td><td><code>10</code>–<code>3600</code></td><td>Git clone、fetch、checkout 和缓存锁等待超时</td><td>C、CR</td></tr><tr><td><code>GIT_ALLOWED_HOSTS</code>†</td><td>API、Worker、MCP</td><td>字符串列表</td><td><code>[]</code></td><td>访问远程仓库时按安全策略配置</td><td>最多 50 项</td><td>允许 clone 或 fetch 的远程主机</td><td>C、CR</td></tr><tr><td><code>ALLOW_INSECURE_GIT_URLS</code>†</td><td>API、Worker、MCP</td><td>布尔值</td><td><code>false</code></td><td>仅隔离环境按风险开启</td><td><code>true</code> 或 <code>false</code></td><td>是否允许不安全的 Git URL</td><td>C、CR</td></tr><tr><td><code>ALLOW_FILE_GIT_URLS</code>†</td><td>API、Worker、MCP</td><td>布尔值</td><td><code>false</code></td><td>需要 <code>file:</code> 地址时显式开启</td><td><code>true</code> 或 <code>false</code></td><td>是否允许 <code>file:</code> Git URL</td><td>C、CR</td></tr><tr><td><code>GITHUB_TOKEN</code></td><td>API、Worker、MCP</td><td>字符串</td><td>空</td><td>仅在仓库未配置专用凭据且远程需要时</td><td>无显式范围</td><td>GitHub 远程仓库备用令牌</td><td>C</td></tr><tr><td><code>GITLAB_TOKEN</code></td><td>API、Worker、MCP</td><td>字符串</td><td>空</td><td>仅在仓库未配置专用凭据且远程需要时</td><td>无显式范围</td><td>GitLab 远程仓库备用令牌</td><td>C</td></tr></tbody></table><p>MCP 与 Worker 读取远程仓库时可以使用各自的缓存，不要求共享 <code>REPOSITORY_STORAGE_PATH</code>。本地仓库路径不会跨主机同步，相关进程必须都能实际访问。</p><h2 id="api-专用配置" tabindex="-1">API 专用配置 <a class="header-anchor" href="#api-专用配置" aria-label="Permalink to &quot;API 专用配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>配置项</th><th>类型</th><th>代码默认值</th><th>必填或条件</th><th>范围</th><th>用途</th><th>来源</th></tr></thead><tbody><tr><td><code>HOST</code></td><td>字符串</td><td><code>127.0.0.1</code></td><td>否</td><td>无显式范围</td><td>API 监听地址</td><td>A</td></tr><tr><td><code>PORT</code></td><td>整数</td><td><code>8000</code></td><td>否</td><td>无显式代码范围</td><td>API 监听端口</td><td>A</td></tr><tr><td><code>REDIS_URL</code></td><td>字符串</td><td><code>redis://localhost:6379/0</code></td><td>登录限流和 Poller 需要可达</td><td>无显式范围</td><td>登录失败计数和仓库 Poller 租约</td><td>A、<code>api/src/ershu/api/poller.py</code></td></tr><tr><td><code>CORS_ORIGINS</code></td><td>字符串列表</td><td><code>[&quot;http://localhost:3000&quot;]</code></td><td>前端跨源访问时配置</td><td>无显式项数上限</td><td>允许携带凭据访问 API 的来源</td><td>A</td></tr><tr><td><code>ACCESS_TOKEN_EXPIRE_MINUTES</code></td><td>整数</td><td><code>30</code></td><td>否</td><td>至少 <code>1</code></td><td>访问令牌有效分钟数</td><td>A</td></tr><tr><td><code>SESSION_ABSOLUTE_TIMEOUT_HOURS</code></td><td>整数</td><td><code>168</code></td><td>否</td><td>至少 <code>1</code></td><td>会话绝对最长小时数</td><td>A</td></tr><tr><td><code>SESSION_COOKIE_NAME</code></td><td>字符串</td><td><code>ershu_session</code></td><td>否</td><td>无显式范围</td><td>会话 Cookie 名称</td><td>A</td></tr><tr><td><code>REFRESH_COOKIE_NAME</code></td><td>字符串</td><td><code>ershu_refresh</code></td><td>否</td><td>无显式范围</td><td>刷新 Cookie 名称</td><td>A</td></tr><tr><td><code>CSRF_COOKIE_NAME</code></td><td>字符串</td><td><code>ershu_csrf</code></td><td>与前端设置保持一致</td><td>无显式范围</td><td>CSRF Cookie 名称</td><td>A</td></tr><tr><td><code>SESSION_COOKIE_SECURE</code></td><td>布尔值</td><td><code>false</code></td><td>生产环境必须为 <code>true</code></td><td><code>true</code> 或 <code>false</code></td><td>限制 Cookie 仅通过安全连接发送</td><td>A</td></tr><tr><td><code>SESSION_COOKIE_SAMESITE</code></td><td>字符串</td><td><code>lax</code></td><td>生产环境校验</td><td>生产环境为 <code>lax</code>、<code>strict</code> 或 <code>none</code></td><td>Cookie SameSite 策略</td><td>A</td></tr><tr><td><code>STREAM_TICKET_EXPIRE_SECONDS</code>†</td><td>整数</td><td><code>300</code></td><td>否</td><td><code>30</code>–<code>3600</code></td><td>新建聊天流式票据的有效秒数</td><td>A</td></tr><tr><td><code>OPAQUE_SERVER_SETUP</code></td><td>字符串</td><td>空</td><td>生产环境必填并保持稳定</td><td>至少 32 个字符，不能是弱值</td><td>OPAQUE 密码注册和登录的服务端设置</td><td>A</td></tr><tr><td><code>POLLER_INTERVAL_SECONDS</code></td><td>整数</td><td><code>30</code></td><td>运行 Poller 时使用</td><td><code>5</code>–<code>3600</code></td><td>两轮仓库计划扫描的最短间隔</td><td>A</td></tr><tr><td><code>POLLER_LEASE_SECONDS</code></td><td>整数</td><td><code>120</code></td><td>运行 Poller 时使用</td><td><code>30</code>–<code>3600</code></td><td>Redis Poller 租约秒数</td><td>A</td></tr><tr><td><code>POLLER_BATCH_SIZE</code></td><td>整数</td><td><code>100</code></td><td>运行 Poller 时使用</td><td><code>1</code>–<code>1000</code></td><td>每轮最多检查的到期仓库数</td><td>A</td></tr></tbody></table><p>生产环境还会要求 HTTPS。反向代理终止 HTTPS 时，需要正确设置代理头与允许来源，不能靠关闭 Cookie 安全检查解决。</p><h2 id="worker-队列、分析和用户提问" tabindex="-1">Worker：队列、分析和用户提问 <a class="header-anchor" href="#worker-队列、分析和用户提问" aria-label="Permalink to &quot;Worker：队列、分析和用户提问&quot;">​</a></h2><p>本节中带 <code>†</code> 的变量可以通过数据库运行时设置覆盖。<code>DOCUMENT_WORKFLOW_ENGINE</code> 只从 Worker 环境读取。</p><table tabindex="0"><thead><tr><th>配置项</th><th>类型</th><th>代码默认值</th><th>必填或条件</th><th>范围</th><th>用途</th><th>来源</th></tr></thead><tbody><tr><td><code>RUN_QUEUE_POLL_INTERVAL_MS</code>†</td><td>整数</td><td><code>1000</code></td><td>否</td><td><code>100</code>–<code>60000</code></td><td>Worker 检查任务队列的间隔</td><td>WR、W</td></tr><tr><td><code>MAX_PARALLEL_REPOSITORY_RUNS</code>†</td><td>整数</td><td><code>3</code></td><td>否</td><td><code>1</code>–<code>100</code></td><td>全项目事实和文档阶段的仓库并发硬上限</td><td>WR、W</td></tr><tr><td><code>DOCUMENT_WORKFLOW_ENGINE</code></td><td>枚举</td><td><code>langgraph</code></td><td>否</td><td><code>langgraph</code> 或 <code>legacy</code></td><td>选择文档生成流程；<code>legacy</code> 保留旧流程</td><td>W</td></tr><tr><td><code>SEARCH_INDEX_BACKGROUND_ENABLED</code>†</td><td>布尔值</td><td><code>true</code></td><td>否</td><td><code>true</code> 或 <code>false</code></td><td>是否让运行先完成，再在后台刷新搜索索引</td><td>WR、W</td></tr><tr><td><code>REPOSITORY_IMPORT_GRAPH_MAX_FILES</code>†</td><td>整数</td><td><code>20000</code></td><td>否</td><td><code>100</code>–<code>100000</code>，或 <code>-1</code> 取消计数上限</td><td>导入关系扫描的源码文件上限</td><td>WR、W</td></tr><tr><td><code>REPOSITORY_IMPORT_GRAPH_MAX_EDGES</code>†</td><td>整数</td><td><code>100000</code></td><td>否</td><td><code>1000</code>–<code>1000000</code>，或 <code>-1</code> 取消计数上限</td><td>每个仓库保留的导入关系上限</td><td>WR、W</td></tr><tr><td><code>ENABLE_ASK_USER</code>†</td><td>布尔值</td><td><code>false</code></td><td>否</td><td><code>true</code> 或 <code>false</code></td><td>是否允许分析 Agent 在新工具轮次向用户提问</td><td>WR、W</td></tr><tr><td><code>ASK_USER_TIMEOUT_MINUTES</code>†</td><td>整数</td><td><code>720</code></td><td>启用提问时使用</td><td><code>1</code>–<code>10080</code></td><td>问题保持可回答的分钟数</td><td>WR、W</td></tr><tr><td><code>ASK_USER_MAX_QUESTIONS_PER_RUN</code>†</td><td>整数</td><td><code>3</code></td><td>启用提问时使用</td><td><code>0</code>–<code>100</code></td><td>单次运行最多提问数</td><td>WR、W</td></tr><tr><td><code>ASK_USER_MIN_ITERATIONS_BETWEEN_QUESTIONS</code>†</td><td>整数</td><td><code>20</code></td><td>启用提问时使用</td><td><code>0</code>–<code>10000</code></td><td>同一运行两次提问之间的最少 Agent 循环次数</td><td>WR、W</td></tr></tbody></table><p>两个导入关系计数设为 <code>-1</code> 只取消该计数上限，遍历安全保护和其他限制仍然存在。</p><h2 id="worker-lsp-和依赖准备" tabindex="-1">Worker：LSP 和依赖准备 <a class="header-anchor" href="#worker-lsp-和依赖准备" aria-label="Permalink to &quot;Worker：LSP 和依赖准备&quot;">​</a></h2><p>LSP 是语言服务器协议。这里的语言服务运行在只读、断网的 Docker 沙箱中；可选依赖准备使用另一个短生命周期下载沙箱。</p><table tabindex="0"><thead><tr><th>配置项</th><th>类型</th><th>代码默认值</th><th>必填或条件</th><th>范围或可选值</th><th>用途</th><th>来源</th></tr></thead><tbody><tr><td><code>REPOSITORY_LSP_ENABLED</code>†</td><td>布尔值</td><td><code>false</code></td><td>使用语言服务时开启</td><td><code>true</code> 或 <code>false</code></td><td>允许创建新的 LSP 会话</td><td>WR、W</td></tr><tr><td><code>REPOSITORY_LSP_RUNTIME</code>†</td><td>枚举</td><td><code>docker</code></td><td>开启 LSP 时使用</td><td>仅 <code>docker</code></td><td>选择 LSP 运行环境</td><td>WR、W</td></tr><tr><td><code>REPOSITORY_LSP_LANGUAGES</code>†</td><td>字符串列表</td><td><code>[&quot;python&quot;]</code></td><td>开启 LSP 时配置</td><td>最多 50 项；当前适配组为 <code>python</code>、<code>typescript</code>、<code>go</code>、<code>rust</code>、<code>clangd</code>、<code>java</code></td><td>启用语言适配组；<code>typescript</code> 同时覆盖 TSX 与 JavaScript</td><td>WR、W</td></tr><tr><td><code>REPOSITORY_LSP_DEFAULT_MODE</code>†</td><td>枚举</td><td><code>strict</code></td><td>开启 LSP 时使用</td><td><code>strict</code> 或 <code>semantic</code></td><td>新能力探测的默认模式</td><td>WR、W</td></tr><tr><td><code>REPOSITORY_LSP_ALLOW_SEMANTIC_MODE</code>†</td><td>布尔值</td><td><code>false</code></td><td>要使用 <code>semantic</code> 时必须显式开启</td><td><code>true</code> 或 <code>false</code></td><td>允许语义模式能力激活</td><td>WR、W</td></tr><tr><td><code>REPOSITORY_DEPENDENCY_RESOLUTION_MODE</code>†</td><td>枚举</td><td><code>disabled</code></td><td>需要准备依赖时改为 <code>managed</code></td><td><code>disabled</code> 或 <code>managed</code></td><td>是否在 LSP 前运行独立依赖准备</td><td>WR、W</td></tr><tr><td><code>REPOSITORY_DEPENDENCY_SOURCE_POLICY</code>†</td><td>枚举</td><td><code>configured_or_public</code></td><td>托管准备时使用</td><td><code>configured_only</code>、<code>configured_or_public</code>、<code>public_only</code></td><td>选择企业源与公共源的使用规则</td><td>WR、W</td></tr><tr><td><code>REPOSITORY_DEPENDENCY_ALLOW_INSECURE_SOURCES</code>†</td><td>布尔值</td><td><code>false</code></td><td>隔离网络确需 HTTP 源时开启</td><td><code>true</code> 或 <code>false</code></td><td>是否允许不安全的依赖源 URL</td><td>WR、W</td></tr><tr><td><code>REPOSITORY_DEPENDENCY_PREPARE_TIMEOUT_SECONDS</code>†</td><td>整数</td><td><code>600</code></td><td>托管准备时使用</td><td><code>30</code>–<code>3600</code></td><td>每条依赖准备命令的超时</td><td>WR、W</td></tr><tr><td><code>REPOSITORY_DEPENDENCY_PREPARE_MAX_MB</code>†</td><td>整数</td><td><code>2048</code></td><td>托管准备时使用</td><td><code>64</code>–<code>16384</code></td><td>单个语言会话保留的已准备依赖大小上限</td><td>WR、W</td></tr><tr><td><code>REPOSITORY_DEPENDENCY_CACHE_PATH</code></td><td>可空字符串</td><td>空</td><td>需要复用下载缓存时填写</td><td>环境变量专用；无显式长度范围</td><td>Worker 主机上的持久依赖下载缓存目录</td><td>W</td></tr><tr><td><code>REPOSITORY_DEPENDENCY_CA_BUNDLE_PATH</code></td><td>可空字符串</td><td>空</td><td>私有依赖源需要额外 CA 时填写</td><td>环境变量专用；无显式长度范围</td><td>Worker 主机上附加 PEM CA 文件路径</td><td>W</td></tr></tbody></table><p>当前托管依赖准备识别 Go、npm、Python 和 Cargo 锁定依赖。Java Maven 与 Gradle 不在这条流程内。</p><h2 id="worker-lsp-容器资源和引用扫描" tabindex="-1">Worker：LSP 容器资源和引用扫描 <a class="header-anchor" href="#worker-lsp-容器资源和引用扫描" aria-label="Permalink to &quot;Worker：LSP 容器资源和引用扫描&quot;">​</a></h2><table tabindex="0"><thead><tr><th>配置项</th><th>类型</th><th>代码默认值</th><th>必填或条件</th><th>范围</th><th>用途</th><th>来源</th></tr></thead><tbody><tr><td><code>LSP_DOCKER_BIN</code>†</td><td>字符串</td><td><code>docker</code></td><td>开启 LSP 时可执行</td><td>非空，最多 255 个字符</td><td>Docker 命令名称或路径</td><td>WR、W</td></tr><tr><td><code>LSP_DOCKER_UID</code>†</td><td>整数</td><td><code>1000</code></td><td>否</td><td><code>0</code>–<code>65535</code></td><td>新容器内的用户编号</td><td>WR、W</td></tr><tr><td><code>LSP_DOCKER_GID</code>†</td><td>整数</td><td><code>1000</code></td><td>否</td><td><code>0</code>–<code>65535</code></td><td>新容器内的组编号</td><td>WR、W</td></tr><tr><td><code>LSP_DOCKER_CPUS</code>†</td><td>字符串</td><td><code>2</code></td><td>否</td><td>非空，最多 255 个字符</td><td>新 LSP 容器的 CPU 限制</td><td>WR、W</td></tr><tr><td><code>LSP_DOCKER_MEMORY</code>†</td><td>字符串</td><td><code>2g</code></td><td>否</td><td>非空，最多 255 个字符</td><td>新 LSP 容器的内存限制</td><td>WR、W</td></tr><tr><td><code>LSP_DOCKER_PIDS_LIMIT</code>†</td><td>整数</td><td><code>256</code></td><td>否</td><td><code>32</code>–<code>4096</code></td><td>新容器的进程数上限</td><td>WR、W</td></tr><tr><td><code>LSP_DOCKER_TMPFS_MB</code>†</td><td>整数</td><td><code>512</code></td><td>否</td><td><code>64</code>–<code>8192</code></td><td>新容器临时文件系统大小</td><td>WR、W</td></tr><tr><td><code>LSP_IDLE_TIMEOUT_SECONDS</code>†</td><td>整数</td><td><code>300</code></td><td>否</td><td><code>30</code>–<code>7200</code></td><td>空闲会话回收阈值</td><td>WR、W</td></tr><tr><td><code>LSP_SESSION_MAX_SECONDS</code>†</td><td>整数</td><td><code>3600</code></td><td>否</td><td><code>60</code>–<code>28800</code></td><td>单个 LSP 会话最长时间</td><td>WR、W</td></tr><tr><td><code>LSP_MAX_SESSIONS_PER_RUN</code>†</td><td>整数</td><td><code>3</code></td><td>否</td><td><code>1</code>–<code>20</code></td><td>单次分析最多 LSP 会话数</td><td>WR、W</td></tr><tr><td><code>LSP_MAX_SESSIONS_PER_WORKER</code>†</td><td>整数</td><td><code>8</code></td><td>否</td><td><code>1</code>–<code>100</code></td><td>单个 Worker 最多 LSP 会话数</td><td>WR、W</td></tr><tr><td><code>LSP_IMAGES</code>†</td><td>字符串映射</td><td>六个默认适配镜像，见下表</td><td>开启对应语言时需要镜像</td><td>最多 50 项；键和值非空</td><td>适配组到 Docker 镜像的映射</td><td>WR、W</td></tr><tr><td><code>LSP_REFERENCE_MAX_SYMBOLS</code>†</td><td>整数</td><td><code>200</code></td><td>否</td><td><code>10</code>–<code>5000</code>，或 <code>-1</code></td><td>每仓库查询语义引用的高价值符号上限</td><td>WR、W</td></tr><tr><td><code>LSP_REFERENCE_MAX_LOCATIONS_PER_SYMBOL</code>†</td><td>整数</td><td><code>80</code></td><td>否</td><td><code>1</code>–<code>5000</code>，或 <code>-1</code></td><td>每个符号接受的引用位置上限</td><td>WR、W</td></tr><tr><td><code>LSP_REFERENCE_MAX_EDGES</code>†</td><td>整数</td><td><code>2000</code></td><td>否</td><td><code>100</code>–<code>100000</code>，或 <code>-1</code></td><td>每仓库保留的可调用对象引用边上限</td><td>WR、W</td></tr><tr><td><code>LSP_REFERENCE_MAX_MODULE_EDGES</code>†</td><td>整数</td><td><code>400</code></td><td>否</td><td><code>0</code>–<code>50000</code>，或 <code>-1</code></td><td>每仓库保留的模块级引用边上限</td><td>WR、W</td></tr><tr><td><code>LSP_REFERENCE_SYMBOL_TIMEOUT_SECONDS</code>†</td><td>整数</td><td><code>6</code></td><td>否</td><td><code>1</code>–<code>120</code></td><td>单个语义引用查询超时</td><td>WR、W</td></tr><tr><td><code>LSP_REFERENCE_TOTAL_TIMEOUT_SECONDS</code>†</td><td>整数</td><td><code>300</code></td><td>否</td><td><code>30</code>–<code>7200</code></td><td>单仓库语义引用扫描总预算</td><td>WR、W</td></tr></tbody></table><p><code>LSP_IMAGES</code> 的代码默认值是：</p><table tabindex="0"><thead><tr><th>适配组</th><th>默认镜像</th></tr></thead><tbody><tr><td><code>python</code></td><td><code>ershu-lsp-python:basedpyright</code></td></tr><tr><td><code>typescript</code></td><td><code>ershu-lsp-typescript:typescript-language-server</code></td></tr><tr><td><code>go</code></td><td><code>ershu-lsp-go:gopls</code></td></tr><tr><td><code>rust</code></td><td><code>ershu-lsp-rust:rust-analyzer</code></td></tr><tr><td><code>clangd</code></td><td><code>ershu-lsp-clangd:clangd</code></td></tr><tr><td><code>java</code></td><td><code>ershu-lsp-java:jdtls</code></td></tr></tbody></table><p>四个引用计数的 <code>-1</code> 只取消计数上限，单符号和总时间预算仍然生效。</p><h2 id="mcp-专用配置" tabindex="-1">MCP 专用配置 <a class="header-anchor" href="#mcp-专用配置" aria-label="Permalink to &quot;MCP 专用配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>配置项</th><th>类型</th><th>代码默认值</th><th>必填或条件</th><th>范围或可选值</th><th>用途</th><th>来源</th></tr></thead><tbody><tr><td><code>MCP_HOST</code></td><td>字符串</td><td><code>127.0.0.1</code></td><td>否</td><td>无显式范围</td><td>MCP 监听地址</td><td>M</td></tr><tr><td><code>MCP_PORT</code></td><td>整数</td><td><code>8001</code></td><td>否</td><td>无显式代码范围</td><td>MCP 监听端口</td><td>M</td></tr><tr><td><code>MCP_BUILD_COMMIT</code></td><td>字符串</td><td>空</td><td>生产环境必填</td><td>为空或完整 40 位十六进制提交号；生产不能空</td><td>向客户端报告实际构建提交</td><td>M</td></tr><tr><td><code>MCP_ENABLE_DNS_REBINDING_PROTECTION</code></td><td>布尔值</td><td><code>true</code></td><td>生产环境必须为 <code>true</code></td><td><code>true</code> 或 <code>false</code></td><td>开启 MCP 传输层 DNS 重绑定防护</td><td>M</td></tr><tr><td><code>MCP_ALLOWED_HOSTS</code></td><td>字符串列表</td><td><code>[&quot;127.0.0.1:*&quot;,&quot;localhost:*&quot;,&quot;[::1]:*&quot;,&quot;testserver&quot;]</code></td><td>生产环境必须非空，并加入外部 Host</td><td>无显式项数上限</td><td>允许的请求 Host</td><td>M</td></tr><tr><td><code>MCP_ALLOWED_ORIGINS</code></td><td>字符串列表</td><td><code>[&quot;http://127.0.0.1:*&quot;,&quot;http://localhost:*&quot;,&quot;http://[::1]:*&quot;]</code></td><td>生产环境必须非空，并加入外部 Origin</td><td>无显式项数上限</td><td>允许的请求 Origin</td><td>M</td></tr></tbody></table><p>生产 MCP 还要求能够读取已安装的 <code>ershu-mcp</code> 包版本。这个条件不是环境变量，但缺失时同样会拒绝启动。</p><h2 id="frontend-构建与开发配置" tabindex="-1">Frontend 构建与开发配置 <a class="header-anchor" href="#frontend-构建与开发配置" aria-label="Permalink to &quot;Frontend 构建与开发配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>配置项</th><th>类型</th><th>代码默认值</th><th>必填或条件</th><th>范围</th><th>用途</th><th>来源</th></tr></thead><tbody><tr><td><code>VITE_API_BASE_URL</code></td><td>字符串</td><td><code>/api/v1</code></td><td>API 不在同源路径时修改</td><td>无显式范围</td><td>浏览器 API 基础路径</td><td>F</td></tr><tr><td><code>VITE_CSRF_COOKIE_NAME</code></td><td>字符串</td><td><code>ershu_csrf</code></td><td>必须与 API 的 <code>CSRF_COOKIE_NAME</code> 一致</td><td>无显式范围</td><td>前端读取 CSRF Cookie 的名称</td><td>F</td></tr><tr><td><code>VITE_DEV_API_PROXY</code></td><td>字符串</td><td><code>http://localhost:8000</code></td><td>仅开发代理按实际 API 修改</td><td>无显式范围</td><td>Vite 将 <code>/api</code> 转发到的目标</td><td>F</td></tr><tr><td><code>VITE_DEV_MCP_PROXY</code></td><td>字符串</td><td><code>http://127.0.0.1:8001</code></td><td>仅开发代理按实际 MCP 修改</td><td>无显式范围</td><td>Vite 将 <code>/mcp</code> 转发到的目标</td><td>F</td></tr></tbody></table><p>Vite 会把这些值写入前端产物。不要在任何 <code>VITE_</code> 变量中放密钥。</p><h2 id="core-的可选真实服务测试变量" tabindex="-1">Core 的可选真实服务测试变量 <a class="header-anchor" href="#core-的可选真实服务测试变量" aria-label="Permalink to &quot;Core 的可选真实服务测试变量&quot;">​</a></h2><p>这些字段来自 <code>core/.env.example</code>，只供显式启用的真实 PostgreSQL 或 Milvus 测试使用，不是 API、Worker 或 MCP 的运行配置。</p><table tabindex="0"><thead><tr><th>配置项</th><th>类型</th><th>示例默认值</th><th>条件</th><th>用途</th><th>来源</th></tr></thead><tbody><tr><td><code>ERSHU_TEST_POSTGRES_URL</code></td><td>字符串</td><td>空</td><td>运行真实 PostgreSQL 测试时填写</td><td>测试数据库地址</td><td><code>core/.env.example</code></td></tr><tr><td><code>ERSHU_TEST_MILVUS_URI</code></td><td>字符串</td><td>空</td><td>运行真实 Milvus 测试时填写</td><td>测试 Milvus 地址</td><td><code>core/.env.example</code></td></tr><tr><td><code>ERSHU_TEST_MILVUS_TOKEN</code></td><td>字符串</td><td>空</td><td>测试 Milvus 开启认证时填写</td><td>测试 Milvus 凭据</td><td><code>core/.env.example</code></td></tr><tr><td><code>ERSHU_TEST_MILVUS_DB_NAME</code></td><td>字符串</td><td><code>default</code></td><td>运行真实 Milvus 测试时使用</td><td>测试 Milvus 数据库</td><td><code>core/.env.example</code></td></tr></tbody></table><h2 id="最容易配错的四点" tabindex="-1">最容易配错的四点 <a class="header-anchor" href="#最容易配错的四点" aria-label="Permalink to &quot;最容易配错的四点&quot;">​</a></h2><ol><li><code>.env.example</code> 的密钥占位符不是可运行默认值。API 与 MCP 会拒绝弱密钥，Worker 会拒绝弱 <code>ENCRYPTION_KEY</code>。</li><li>模型通道不通过环境变量配置。管理员应在网页或 API 中保存 LLM、嵌入和重排通道。</li><li>数据库运行时覆盖只作用于带 <code>†</code> 的字段。数据库地址、密钥、Cookie、CORS 和 MCP 传输安全边界仍要通过进程环境部署。</li><li>修改运行时字段也不是追溯改写：多数值只影响新的轮询、会话、扫描、容器或索引批次，已经运行的工作不会被重新配置。</li></ol>',43)])])}const C=t(r,[["render",a]]);export{l as __pageData,C as default};
